functions.logger:
void logger(enum LOGGING_TAG tag, const char *message)
{
    time_t now;
    time(&now);
    char *time_now = ctime(&now);
    time_now[strlen(time_now) - 1] = 0;
    switch (tag)
    {
    case INFO_TAG:
        printf("%s "
               "\e[1m"
               "[%s]"
               "\e[m"
               ": %s\n",
               time_now, "INFO", message);
        break;
    case ERROR_TAG:
        fprintf(stderr,
                "%s "
                "\x1B[31m"
                "\e[1m"
                "[%s]"
                "\e[m"
                "\x1B[0m"
                ": %s (%s)\n",
                time_now, "ERROR", message, strerror((*__errno_location())));
        break;
    case WARNING_TAG:
        printf("%s "
               "\e[1m"
               "[%s]"
               "\e[m"
               ": %s\n",
               time_now, "WARNING", message);
        break;
    default:
    }
}

