functions.addFile:
struct file_node *addFile(struct file_node *head, const char *path)
{
    struct file_node *newNode = (struct file_node *)malloc(sizeof(struct file_node));
    strcpy(newNode->path, path);
    newNode->next = head;
    return newNode;
